public void setCreationDate(String username, Date creationDate) throws UserNotFoundException {
  if (isReadOnly()) {
    throw new UnsupportedOperationException();
  }
  Connection con = null;
  PreparedStatement pstmt = null;
  try {
    con = DbConnectionManager.getConnection();
    pstmt = con.prepareStatement(UPDATE_CREATION_DATE);
    pstmt.setString(1, StringUtils.dateToMillis(creationDate));
    pstmt.setString(2, username);
    pstmt.executeUpdate();
  } catch (SQLException | RuntimeException e) {
    if (e instanceof IndexOutOfBoundsException) {
      // Handle IndexOutOfBoundsException
      Log.error("Index out of bounds: ", e);
    } else if (e instanceof ExceptionInInitializerError ||
               e instanceof ClassCastException ||
               e instanceof NullPointerException ||
               e instanceof UnsupportedOperationException ||
               e instanceof IllegalArgumentException ||
               e instanceof LinkageError ||
               e instanceof SecurityException) {
      // Handle other runtime exceptions
      Log.error("Runtime exception: ", e);
    } else {
      // Handle SQLException and rethrow as UserNotFoundException
      throw new UserNotFoundException(e);
    }
  } finally {
    try {
      if (pstmt != null) pstmt.close();
    } catch (Exception e) {
      Log.error(e);
    }
    try {
      if (con != null) con.close();
    } catch (Exception e) {
      Log.error(e);
    }
  }
}
